body.query:
query summary($q: String, $predicate: Predicate, $hasPredicate: Predicate, $size: Int, $from: Int, $checklistKey: ID){
  search: occurrenceSearch(q: $q, predicate: $predicate) {
    documents(size: 0) {
      total
    }
    cardinality {
      total: familyKey(checklistKey: $checklistKey)
    }
    facet {
      results: familyKey(size: $size, from: $from, checklistKey: $checklistKey) {
        key
        count
        occurrences {
          metaPredicate
          _meta
        }
        entity: taxonMatch(checklistKey: $checklistKey) {
          usage {
            name
          }
          classification {
            name
            key
            rank
          }
          iucnStatus
          iucnStatusCode
        }
      }
    }
  }
  isNotNull: occurrenceSearch(q: $q, predicate: $hasPredicate) {
    documents(size: 0) {
      total
    }
  }
}
